// Sets up self-hosted Tesseract assets for the local, offline Auto-rotate (OSD)
// feature, under public/tesseract/. Run once: `npm run setup:ocr`.
//
//  - worker.min.js            (tesseract.js worker)
//  - the 3 legacy cores       (relaxedsimd / simd / plain — non-LSTM; OSD needs
//                              the legacy engine, and the browser picks one by
//                              capability, so all three must be present)
//  - osd.traineddata          (downloaded from the official tessdata repo)
//
// These are large binaries, so they're git-ignored and regenerated by this
// script rather than committed.
import { mkdirSync, copyFileSync, existsSync, writeFileSync, statSync } from 'fs';
import { fileURLToPath } from 'url';
import { dirname, join } from 'path';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const out = join(root, 'public', 'tesseract');
mkdirSync(out, { recursive: true });

const copies = [
  ['node_modules/tesseract.js/dist/worker.min.js', 'worker.min.js'],
  ['node_modules/tesseract.js-core/tesseract-core.wasm', 'tesseract-core.wasm'],
  ['node_modules/tesseract.js-core/tesseract-core.wasm.js', 'tesseract-core.wasm.js'],
  ['node_modules/tesseract.js-core/tesseract-core-simd.wasm', 'tesseract-core-simd.wasm'],
  ['node_modules/tesseract.js-core/tesseract-core-simd.wasm.js', 'tesseract-core-simd.wasm.js'],
  ['node_modules/tesseract.js-core/tesseract-core-relaxedsimd.wasm', 'tesseract-core-relaxedsimd.wasm'],
  ['node_modules/tesseract.js-core/tesseract-core-relaxedsimd.wasm.js', 'tesseract-core-relaxedsimd.wasm.js'],
];

for (const [src, name] of copies) {
  const from = join(root, src);
  if (!existsSync(from)) {
    console.error(`MISSING ${src} — run \`npm install\` first.`);
    process.exit(1);
  }
  copyFileSync(from, join(out, name));
  console.log('copied', name);
}

const tdPath = join(out, 'osd.traineddata');
if (existsSync(tdPath) && statSync(tdPath).size > 1_000_000) {
  console.log('osd.traineddata already present, skipping download');
} else {
  const url = 'https://raw.githubusercontent.com/tesseract-ocr/tessdata/main/osd.traineddata';
  console.log('downloading osd.traineddata …');
  const res = await fetch(url);
  if (!res.ok) {
    console.error(`download failed: ${res.status} ${res.statusText}`);
    process.exit(1);
  }
  const buf = Buffer.from(await res.arrayBuffer());
  writeFileSync(tdPath, buf);
  console.log(`wrote osd.traineddata (${(buf.length / 1048576).toFixed(1)} MB)`);
}

console.log('done — Tesseract OSD assets ready in public/tesseract/');
